// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address actor, uint256 preBalance, uint256 sendValue) public {
        uint256 max = type(uint256).max;
        sendValue = bound(sendValue, 0, max - preBalance);
        vm.assume(preBalance <= max - sendValue);
        vm.deal(actor, preBalance + sendValue);
        vm.startPrank(actor);
        if (preBalance > 0) {
            c.addToBalance{value: preBalance}();
        }
        uint256 balanceBefore = c.getBalance(actor);
        c.addToBalance{value: sendValue}();
        vm.stopPrank();
        uint256 balanceAfter = c.getBalance(actor);
        assertTrue(balanceAfter == balanceBefore + sendValue);
    }
}
